<?php $workPath='/work/project/'.$project['id'];$issuePath='/work/issue/'.$issue['id'];$inactive=$issue['deleted_at']!==null||$issue['archived_at']!==null;$favorite=Db::one("SELECT entity_id FROM work_favorites WHERE workspace_id=? AND entity='issue' AND entity_id=?",[$workspace['id'],$issue['id']]); ?>
<div class="topline"><a href="<?= $workPath ?>"><?= e($project['name']) ?></a><span><?= e($issue['key']) ?></span></div><header class="page-header work-issue-header"><div><div class="work-issue-kicker"><span class="work-state-dot" data-work-color="<?= e($issue['state_color']) ?>"></span><strong><?= e($issue['key']) ?></strong><span class="badge"><?= e($issue['state_name']) ?></span><span class="work-priority priority-<?= e($issue['priority']) ?>"><?= e(WorkService::PRIORITIES[$issue['priority']]) ?></span></div><h1><?= e($issue['title']) ?></h1><p class="muted">Updated <?= e($issue['updated_at']) ?> · v<?= e($issue['version']) ?></p></div><form method="post" action="/work/workspace/<?= e($workspace['id']) ?>/favorite"><?= csrf_field() ?><input type="hidden" name="entity" value="issue"><input type="hidden" name="entity_id" value="<?= e($issue['id']) ?>"><input type="hidden" name="on" value="<?= $favorite?'0':'1' ?>"><button class="secondary"><?= $favorite?'★ Remove favourite':'☆ Favourite' ?></button></form></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php if($inactive): ?><section class="card"><h2><?= $issue['deleted_at']!==null?'This work item is in Trash.':'This work item is archived.' ?></h2><p class="muted">Its description, relationships and history are preserved.</p><form method="post" action="<?= $workPath ?>/issues/<?= e($issue['id']) ?>/lifecycle"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($issue['version']) ?>"><input type="hidden" name="action" value="<?= $issue['deleted_at']!==null?'restore':'unarchive' ?>"><button>Restore work item</button></form></section><?php endif; ?>
<?php if($issue['intake_status']!=='accepted'&&!$inactive): ?><section class="card"><h2><?= $issue['intake_status']==='pending'?'Intake · awaiting triage':'Rejected request' ?></h2><p class="muted">This request is kept outside active project work until accepted.</p><div class="hero-actions"><?php foreach(['accept'=>'Accept into project','reject'=>'Reject request'] as $action=>$label):if($issue['intake_status']==='rejected'&&$action==='reject')continue; ?><form method="post" action="<?= $workPath ?>/issues/<?= e($issue['id']) ?>/lifecycle"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($issue['version']) ?>"><input type="hidden" name="action" value="<?= $action ?>"><button class="secondary"><?= $label ?></button></form><?php endforeach; ?></div></section><?php endif; ?>
<div class="two-col work-issue-detail"><section class="card"><h2>Description</h2><?php if($issue['description']!==''): ?><div class="work-markdown"><?= WorkService::markdown($issue['description']) ?></div><?php else: ?><p class="muted">No description added.</p><?php endif; ?><?php if($issue['parent_id']): $parent=WorkIssueService::get((int)$issue['parent_id']); ?><p class="footnote">Parent: <a href="/work/issue/<?= e($parent['id']) ?>"><?= e($parent['key'].' · '.$parent['title']) ?></a></p><?php endif; ?><dl class="work-properties"><div><dt>Type</dt><dd><?= e(WorkService::TYPES[$issue['issue_type']]) ?></dd></div><div><dt>Fix version</dt><dd><?php if($issue['fix_version_id']): ?><a href="<?= $workPath ?>?tab=releases"><?= e($issue['fix_version_name']??'Release') ?></a><?php else: ?>Not assigned<?php endif; ?></dd></div><div><dt>Assignees</dt><dd><?= e(implode(', ',array_column($issue['assignees'],'name'))?:'Not assigned') ?></dd></div><div><dt>Start date</dt><dd><?= e($issue['start_date']??'Not set') ?></dd></div><div><dt>Due date</dt><dd><?= e($issue['due_date']??'Not set') ?></dd></div><div><dt>Estimate</dt><dd><?= $issue['estimate']!==null?e($issue['estimate']).' points':'Not set' ?></dd></div></dl><?php if($issue['labels']): ?><div class="work-labels"><?php foreach($issue['labels'] as $label): ?><span data-work-color="<?= e($label['color']) ?>"><?= e($label['name']) ?></span><?php endforeach; ?></div><?php endif; ?></section><section class="card"><h2>Sub-issues</h2><?php if(!$children): ?><p class="muted">Break this work item into smaller steps.</p><?php else:foreach($children as $child): ?><a class="work-compact-issue" href="/work/issue/<?= e($child['id']) ?>"><span class="work-state-dot" data-work-color="<?= e($child['state_color']) ?>"></span><span><small><?= e($project['identifier'].'-'.$child['sequence']) ?></small><strong><?= e($child['title']) ?></strong></span><span class="badge"><?= e($child['state_name']) ?></span></a><?php endforeach;endif; ?><?php if(!$inactive): ?><details><summary>+ Add sub-issue</summary><form class="stack" method="post" action="<?= $workPath ?>/issues"><?= csrf_field() ?><input type="hidden" name="parent_id" value="<?= e($issue['id']) ?>"><input type="hidden" name="issue_type" value="subtask"><label>Title<input name="title" maxlength="250" required></label><label>Description<textarea name="description" maxlength="30000" rows="3"></textarea></label><button class="secondary">Create sub-issue</button></form></details><?php endif; ?></section></div>
<?php if(!$inactive): ?><details class="card work-edit-issue" id="work-edit-issue"><summary><strong>Edit work item</strong></summary><?php $editIssue=$issue;$issueFormAction=$workPath.'/issues/'.$issue['id'].'/save';require __DIR__.'/issue-form.php'; ?></details><?php endif; ?>
<section class="card" id="work-relations"><div class="section-heading"><h2>Relationships &amp; dependencies</h2><span class="badge"><?= count($relations) ?> links</span></div><?php if(!$relations): ?><p class="muted">Link related work or track blockers.</p><?php else:foreach($relations as $relation):$other=WorkIssueService::get((int)($relation['from_id']===$issue['id']?$relation['to_id']:$relation['from_id']));$relationLabel=$relation['kind']==='blocks'?($relation['from_id']===$issue['id']?'Blocks':'Blocked by'):($relation['kind']==='duplicates'?'Duplicates':'Related to'); ?><article class="studio-record-row"><div><small><?= e($relationLabel) ?></small><a href="/work/issue/<?= e($other['id']) ?>"><?= e($other['key'].' · '.$other['title']) ?></a></div><form method="post" action="<?= $issuePath ?>/relation/<?= e($relation['id']) ?>/remove"><?= csrf_field() ?><button class="quiet">Remove link</button></form></article><?php endforeach;endif; ?><?php if(!$inactive&&$relatedChoices): ?><form class="work-inline-form" method="post" action="<?= $issuePath ?>/relations"><?= csrf_field() ?><label>Relationship<select name="kind"><option value="relates">Related to</option><option value="blocks">Blocks</option><option value="duplicates">Duplicates</option></select></label><label>Work item<select name="related_id"><?php foreach($relatedChoices as $choice): ?><option value="<?= e($choice['id']) ?>"><?= e($project['identifier'].'-'.$choice['sequence'].' · '.$choice['title']) ?></option><?php endforeach; ?></select></label><button class="secondary">Add link</button></form><?php endif; ?></section>
<section class="card" id="work-comments"><div class="section-heading"><h2>Conversation</h2><span class="badge"><?= count($comments) ?> comments</span></div><?php if(!$comments): ?><p class="muted">Keep decisions and updates with the work.</p><?php else:foreach($comments as $comment): ?><article class="work-comment"><header><span class="work-avatar"><?= e(mb_substr($comment['author_name'],0,1)) ?></span><strong><?= e($comment['author_name']) ?></strong><time><?= e($comment['updated_at']) ?></time></header><div class="work-markdown"><?= WorkService::markdown($comment['body']) ?></div><details><summary>Edit comment</summary><form class="stack" method="post" action="<?= $issuePath ?>/comments"><?= csrf_field() ?><input type="hidden" name="comment_id" value="<?= e($comment['id']) ?>"><input type="hidden" name="version" value="<?= e($comment['version']) ?>"><textarea name="body" maxlength="20000" rows="3" required><?= e($comment['body']) ?></textarea><button class="secondary">Save comment</button></form></details><form method="post" action="<?= $issuePath ?>/comment/<?= e($comment['id']) ?>/remove" data-confirm="Remove this comment from the conversation?"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($comment['version']) ?>"><button class="quiet">Remove comment</button></form></article><?php endforeach;endif; ?><?php if(!$inactive): ?><form class="stack" method="post" action="<?= $issuePath ?>/comments"><?= csrf_field() ?><label>Add a comment<textarea name="body" maxlength="20000" rows="3" required placeholder="An update, decision or question..."></textarea></label><button>Post comment</button></form><?php endif; ?></section>
<div class="two-col"><section class="card" id="work-time"><div class="section-heading"><h2>Time tracking</h2><span class="badge"><?= array_sum(array_column($timeEntries,'minutes')) ?> minutes</span></div><?php if(!$inactive): ?><form class="work-inline-form" method="post" action="<?= $issuePath ?>/timer"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $timer?'stop':'start' ?>"><?php if($timer): ?><strong data-work-timer="<?= e($timer['started_at']) ?>">Running</strong><label>Correct minutes (optional)<input name="minutes" type="number" min="1" max="1440" placeholder="Measured if empty"></label><?php endif; ?><button class="secondary"><?= $timer?'Stop & save timer':'Start timer' ?></button></form><details><summary>+ Manual time entry</summary><form class="form-grid" method="post" action="<?= $issuePath ?>/time"><?= csrf_field() ?><label>Date<input name="on_date" type="date" value="<?= e(date('Y-m-d')) ?>" required></label><label>Minutes<input name="minutes" type="number" min="1" max="1440" required></label><label>Person<select name="person_id"><?php foreach($people as $person):if(!$person['active'])continue; ?><option value="<?= e($person['id']) ?>" <?= $person['is_self']?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach; ?></select></label><label class="full">Notes<textarea name="notes" maxlength="2000" rows="2"></textarea></label><div class="full"><button class="secondary">Log time</button></div></form></details><?php endif; ?><?php foreach($timeEntries as $entry): ?><article class="work-time-row"><div><strong><?= e($entry['minutes']) ?> min · <?= e($entry['person_name']) ?></strong><small><?= e($entry['on_date']) ?><?= $entry['notes']?' · '.e($entry['notes']):'' ?></small></div><form method="post" action="<?= $issuePath ?>/time/<?= e($entry['id']) ?>/remove" data-confirm="Remove this time entry?"><?= csrf_field() ?><button class="quiet">Remove</button></form></article><?php endforeach; ?><p class="footnote">Time logs do not charge a client or change Money balances.</p></section><section class="card" id="work-files"><h2>Attachments</h2><?php if(!$attachments): ?><p class="muted">Add references, screenshots or project files.</p><?php else:foreach($attachments as $file): ?><a class="work-file-link" href="/documents/<?= e($file['id']) ?>/download" hx-boost="false"><?= icon('folder') ?><span><strong><?= e($file['original_name']) ?></strong><small><?= number_format($file['bytes']/1024,1) ?> KB</small></span></a><?php endforeach;endif; ?><?php if(!$inactive): ?><form class="stack" method="post" action="<?= $issuePath ?>/attachments" enctype="multipart/form-data" hx-boost="false"><?= csrf_field() ?><label>Upload attachment<input type="file" name="file" required></label><button class="secondary">Attach file</button></form><p class="footnote">Supported document and image formats · up to 25 MB. Attachments are also available in Documents.</p><?php endif; ?></section></div>
<section class="card"><h2>Work-item activity</h2><?php foreach($activity as $event): ?><article class="studio-activity"><span class="studio-activity-mark"><?= icon('check') ?></span><div><strong><?= e(str_replace('.',' · ',$event['event'])) ?></strong><p><?= e($event['actor_name']) ?><?= $event['detail']!==''?' · '.e(mb_strimwidth($event['detail'],0,120,'…')):'' ?></p></div><time><?= e($event['created_at']) ?></time></article><?php endforeach; ?></section>
<?php if(!$inactive): ?><section class="card"><div class="section-heading"><h2>Archive or remove</h2><div class="hero-actions"><?php foreach(['archive'=>'Archive work item','trash'=>'Move to Trash'] as $action=>$label): ?><form method="post" action="<?= $workPath ?>/issues/<?= e($issue['id']) ?>/lifecycle" data-confirm="<?= $action==='trash'?'Move this work item to Trash? Its history is preserved.':'Archive this work item? It can be restored later.' ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($issue['version']) ?>"><input type="hidden" name="action" value="<?= $action ?>"><button class="secondary"><?= $label ?></button></form><?php endforeach; ?></div></div></section><?php endif; ?>
